-- C04 OPTIONAL SCOPED SNAPSHOT — WRITES into the same database. Generated by build-and-verify.py.
-- Only inside the release slot, right before 02-apply-writes.sql, if the coordinator wants a copy of the rows
-- C04 guards (promos, promo_items) besides the daily backup. No data leaves the project; no grant is added.
-- Fails (nothing changes) if a previous snapshot with the same name exists. Drop it when the coordinator says:
--   drop table ops_backup.promos_pre_c04, ops_backup.promo_items_pre_c04;
-- repeatable read: both tables are copied from one consistent view of the database.
begin isolation level repeatable read;
create schema if not exists ops_backup;
revoke all on schema ops_backup from public, anon, authenticated, service_role;
create table ops_backup.promos_pre_c04 as table public.promos;
create table ops_backup.promo_items_pre_c04 as table public.promo_items;
revoke all on ops_backup.promos_pre_c04, ops_backup.promo_items_pre_c04 from public, anon, authenticated, service_role;
select 'promos' as copied, (select count(*) from public.promos) as live, (select count(*) from ops_backup.promos_pre_c04) as snapshot
union all select 'promo_items', (select count(*) from public.promo_items), (select count(*) from ops_backup.promo_items_pre_c04);
commit;
